B.aGN=new A.fB("kilo","Kilo","kg","Sabah kalk\u0131nca, tuvalete gittikten sonra, bir \u015fey yiyip i\xe7meden, ince k\u0131yafetle tart\u0131l.","Tart\u0131y\u0131 hal\u0131 yerine d\xfcz ve sert bir zemine koy. Her hafta ayn\u0131 tart\u0131y\u0131 kullan.",B.kw,25,350)
B.aGJ=new A.fB("bel","Bel","cm","En alttaki kaburga kemi\u011finle kal\xe7a kemi\u011finin \xfcst ucunun tam ortas\u0131. \xc7o\u011fu ki\u015fide g\xf6bek deli\u011finin biraz \xfcst\xfc.","Ayakta, karn\u0131n\u0131 i\xe7ine \xe7ekmeden dur. Normal nefes verdikten sonra \xf6l\xe7. Bu, sa\u011fl\u0131k a\xe7\u0131s\u0131ndan en \xf6nemli \xf6l\xe7\xfc.",B.kw,40,220)
B.aGL=new A.fB("kalca","Kal\xe7a","cm","Kal\xe7an\u0131n en geni\u015f, en \xe7\u0131k\u0131nt\u0131l\u0131 yeri. Yandan aynaya bakarak bul.","Ayaklar\u0131n\u0131 biti\u015ftir, kal\xe7a kaslar\u0131n\u0131 s\u0131kma.",B.kw,50,250)
