B.aGP=new A.fB("gobek","G\xf6bek","cm","Tam g\xf6bek deli\u011finin hizas\u0131.","Evde en kolay tekrarlanan \xf6l\xe7\xfc; kar\u0131n b\xf6lgesindeki de\u011fi\u015fimi g\xf6sterir.",B.vi,40,230)
B.aGM=new A.fB("gogus","G\xf6\u011f\xfcs","cm","G\xf6\u011fs\xfcn en geni\u015f yeri (meme ucu hizas\u0131), kollar yanda.","Her \xf6l\xe7\xfcmde ayn\u0131 s\xfctyeni (tercihen sporcu s\xfctyeni) giy. Regl \xf6ncesi birka\xe7 g\xfcn de\u011fi\u015febilir.",B.vi,50,220)
